// Fictional partner places. `venue` links an offer to a group venue; the server works that out itself.
const PERK_OFFERS = [
  { id: 1, business: 'Shelf Life Café', type: 'cafe', offer: 'Free table for your group, 20% off drinks and cakes', conditions: 'During your group’s meetup', area: 'Library ground floor', venue: 'Library ground-floor café area' },
  { id: 2, business: 'Harbour Bean', type: 'cafe', offer: '15% off hot drinks', conditions: 'Mon to Thu, before 5pm', area: '4 min walk from campus' },
  { id: 3, business: 'The Dice Cupboard', type: 'games', offer: '10% off table fees and drinks', conditions: 'Mon to Thu', area: '5 min walk from campus' },
  { id: 4, business: 'Meeple & Mug', type: 'games', offer: 'Free games library with any drink', conditions: 'Sun to Wed', area: '12 min walk from campus' },
  { id: 5, business: 'Tidewall Climbing', type: 'climbing', offer: 'Half-price first visit, shoe hire included', conditions: 'Weekdays, before 4pm', area: '10 min by bus' },
  { id: 6, business: 'Little Pier Picturehouse', type: 'cinema', offer: '£2 off any ticket', conditions: 'Sun to Thu', area: '20 min walk from campus' },
  { id: 7, business: 'Noodle Dock', type: 'food', offer: '15% off bowls', conditions: 'Mon to Fri, 12 to 3pm', area: '8 min walk from campus' },
];
function perksFor(p) {
  const venue = p.group && p.group.slot && p.group.slot.venue.name;
  const offers = PERK_OFFERS.map(({ venue: v, ...o }) => Object.assign(o, { is_group_venue: !!venue && v === venue }));
  const mine = offers.find(o => o.is_group_venue);
  return { group_venue_offer_id: mine ? mine.id : null, offers };
}
const clone = o => JSON.parse(JSON.stringify(o));

// After week 2: the 2-week taster check is open, and week 3 is next.
const taster = clone(S.active);
Object.assign(taster.participant.session, { week: 3, first_time: false });
taster.participant.taster = { weeks: 2, check_open: true, answered: null };
S.taster = taster;

// Week 8, end of the cycle: the meetups are over and the private "again?" question is open.
const end = clone(S.active);
end.participant.session = null;
end.participant.group.members.forEach((m, i) => { m.id = 101 + i; m.coming = 'none'; });
end.participant.cycle = { week: 8, weeks: 8, again_open: true, again_answered: false, my_again: null };
S.cycleend = end;

// Bring a friend: your own link while you're on the waiting list. `with` is set once someone joins with it.
S.waiting.participant.friend = { link: '#demo', with: null };

// Perks for verified members only: waiting list, offered a place, in a group, paused, and at the end of the cycle.
['waiting', 'offered', 'active', 'arrival', 'notgoing', 'weekvote', 'paused', 'taster', 'cycleend'].forEach(k => { S[k].participant.perks = perksFor(S[k].participant); });
